struct Color { uint8_t r,g,b,a; };
static Color rgb(uint8_t r,uint8_t g,uint8_t b){return {r,g,b,255};}
static constexpr int W=1000,H=590,OX=50,OY=88,WW=1100,WH=760;
static std::vector<uint8_t> pix(W*H*4,255);
static std::vector<std::vector<uint8_t>> undoStack,redoStack;
static GLuint tex=0;
enum class Tool{Pencil,Line,Rect,Ellipse,Eraser,Text};
static Tool tool=Tool::Pencil; static Color fg=rgb(20,20,20); static bool fillShape=false;
static bool drawing=false,textMode=false; static int sx=0,sy=0,lx=0,ly=0,tx=0,ty=0; static std::string text;
static const std::array<Color,20> colors={rgb(0,0,0),rgb(255,255,255),rgb(128,128,128),rgb(192,192,192),rgb(128,0,0),rgb(255,0,0),rgb(128,64,0),rgb(255,128,0),rgb(128,128,0),rgb(255,255,0),rgb(0,128,0),rgb(0,255,0),rgb(0,128,128),rgb(0,255,255),rgb(0,0,128),rgb(0,128,255),rgb(128,0,128),rgb(255,0,255),rgb(64,64,192),rgb(64,192,255)};

static void clearCanvas(Color c=rgb(255,255,255)){for(int y=0;y<H;y++)for(int x=0;x<W;x++){auto i=(y*W+x)*4;pix[i]=c.r;pix[i+1]=c.g;pix[i+2]=c.b;pix[i+3]=255;}}
static void saveState(){undoStack.push_back(pix);if(undoStack.size()>30)undoStack.erase(undoStack.begin());redoStack.clear();}
static void undo(){if(undoStack.empty())return;redoStack.push_back(pix);pix=undoStack.back();undoStack.pop_back();}
static void redo(){if(redoStack.empty())return;undoStack.push_back(pix);pix=redoStack.back();redoStack.pop_back();}
static bool canvasPoint(int x,int y){return x>=OX&&x<OX+W&&y>=OY&&y<OY+H;}
static void put(int x,int y,Color c){if(x<0||y<0||x>=W||y>=H)return;size_t i=(y*W+x)*4;pix[i]=c.r;pix[i+1]=c.g;pix[i+2]=c.b;pix[i+3]=c.a;}
static void line(int x0,int y0,int x1,int y1,Color c,int width=3){int dx=std::abs(x1-x0),sx=x0<x1?1:-1,dy=-std::abs(y1-y0),sy=y0<y1?1:-1,e=dx+dy;while(true){int r=width/2;for(int yy=-r;yy<=r;yy++)for(int xx=-r;xx<=r;xx++)if(xx*xx+yy*yy<=r*r+1)put(x0+xx,y0+yy,c);if(x0==x1&&y0==y1)break;int e2=2*e;if(e2>=dy){e+=dy;x0+=sx;}if(e2<=dx){e+=dx;y0+=sy;}}}
static void rectangle(int x0,int y0,int x1,int y1,Color c,bool fill){if(x0>x1)std::swap(x0,x1);if(y0>y1)std::swap(y0,y1);x0=std::max(0,x0);y0=std::max(0,y0);x1=std::min(W-1,x1);y1=std::min(H-1,y1);if(fill){for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++)put(x,y,c);}else{line(x0,y0,x1,y0,c);line(x1,y0,x1,y1,c);line(x1,y1,x0,y1,c);line(x0,y1,x0,y0,c);}}
static void ellipse(int x0,int y0,int x1,int y1,Color c,bool fill){int cx=(x0+x1)/2,cy=(y0+y1)/2,rx=std::abs(x1-x0)/2,ry=std::abs(y1-y0)/2;if(!rx||!ry){line(x0,y0,x1,y1,c);return;}for(int y=-ry;y<=ry;y++){double q=1.0-(double)y*y/(ry*ry);int s=(int)std::round(rx*std::sqrt(std::max(0.0,q)));if(fill)for(int x=-s;x<=s;x++)put(cx+x,cy+y,c);else{put(cx-s,cy+y,c);put(cx+s,cy+y,c);}}}

static const char* glyph(char ch){static const std::pair<char,const char*> g[]={
{'A',"01110;10001;10001;11111;10001;10001;10001"},{'B',"11110;10001;10001;11110;10001;10001;11110"},{'C',"01111;10000;10000;10000;10000;10000;01111"},{'D',"11110;10001;10001;10001;10001;10001;11110"},{'E',"11111;10000;10000;11110;10000;10000;11111"},{'F',"11111;10000;10000;11110;10000;10000;10000"},{'G',"01111;10000;10000;10111;10001;10001;01110"},{'H',"10001;10001;10001;11111;10001;10001;10001"},{'I',"11111;00100;00100;00100;00100;00100;11111"},{'J',"00111;00010;00010;00010;10010;10010;01100"},{'K',"10001;10010;10100;11000;10100;10010;10001"},{'L',"10000;10000;10000;10000;10000;10000;11111"},{'M',"10001;11011;10101;10101;10001;10001;10001"},{'N',"10001;11001;10101;10011;10001;10001;10001"},{'O',"01110;10001;10001;10001;10001;10001;01110"},{'P',"11110;10001;10001;11110;10000;10000;10000"},{'Q',"01110;10001;10001;10001;10101;10010;01101"},{'R',"11110;10001;10001;11110;10100;10010;10001"},{'S',"01111;10000;10000;01110;00001;00001;11110"},{'T',"11111;00100;00100;00100;00100;00100;00100"},{'U',"10001;10001;10001;10001;10001;10001;01110"},{'V',"10001;10001;10001;10001;10001;01010;00100"},{'W',"10001;10001;10001;10101;10101;11011;10001"},{'X',"10001;10001;01010;00100;01010;10001;10001"},{'Y',"10001;10001;01010;00100;00100;00100;00100"},{'Z',"11111;00001;00010;00100;01000;10000;11111"},{'0',"01110;10001;10011;10101;11001;10001;01110"},{'1',"00100;01100;00100;00100;00100;00100;01110"},{'2',"01110;10001;00001;00010;00100;01000;11111"},{'3',"11110;00001;00001;01110;00001;00001;11110"},{'4',"00010;00110;01010;10010;11111;00010;00010"},{'5',"11111;10000;10000;11110;00001;00001;11110"},{'6',"01110;10000;10000;11110;10001;10001;01110"},{'7',"11111;00001;00010;00100;01000;01000;01000"},{'8',"01110;10001;10001;01110;10001;10001;01110"},{'9',"01110;10001;10001;01111;00001;00001;01110"},{'!',"00100;00100;00100;00100;00100;00000;00100"},{'?',"01110;10001;00001;00010;00100;00000;00100"},{'-',"00000;00000;00000;11111;00000;00000;00000"},{'.',"00000;00000;00000;00000;00000;00100;00100"},{' ',"00000;00000;00000;00000;00000;00000;00000"}};char u=(char)std::toupper((unsigned char)ch);for(auto&p:g)if(p.first==u)return p.second;return g[0].second;}
static void textPixel(int x,int y,char ch,Color c,int s=3){const char*g=glyph(ch);int r=0,col=0;for(int i=0;g[i];i++){if(g[i]==';'){r++;col=0;continue;}if(g[i]=='1')for(int yy=0;yy<s;yy++)for(int xx=0;xx<s;xx++)put(x+col*s+xx,y+r*s+yy,c);col++;}}
static void drawText(int x,int y,const std::string&s,Color c,int scale=3){int ox=x;for(char ch:s){if(ch=='\n'){y+=8*scale;x=ox;}else{textPixel(x,y,ch,c,scale);x+=6*scale;}}}
static void quad(float a,float b,float c,float d,Color col){glColor4f(col.r/255.f,col.g/255.f,col.b/255.f,col.a/255.f);glBegin(GL_QUADS);glVertex2f(a,b);glVertex2f(c,b);glVertex2f(c,d);glVertex2f(a,d);glEnd();}
static void outline(float a,float b,float c,float d,Color col){glColor4f(col.r/255.f,col.g/255.f,col.b/255.f,1);glBegin(GL_LINE_LOOP);glVertex2f(a,b);glVertex2f(c,b);glVertex2f(c,d);glVertex2f(a,d);glEnd();}
static void render(){glClearColor(.16f,.18f,.21f,1);glClear(GL_COLOR_BUFFER_BIT);glMatrixMode(GL_PROJECTION);glLoadIdentity();glOrtho(0,WW,WH,0,-1,1);glMatrixMode(GL_MODELVIEW);glLoadIdentity();quad(0,0,WW,76,rgb(38,41,48));drawText(18,14,"PAINTAPPX",rgb(255,255,255),3);const char* labels[]={"PENCIL","ERASER","LINE","RECT","ELLIPSE","TEXT","FILL","UNDO","REDO","CLEAR","SAVE"};int xs[]={12,78,144,202,280,366,436,510,582,654,726};int xe[]={72,138,196,274,360,430,504,576,648,720,792};for(int i=0;i<11;i++){quad(xs[i],46,xe[i],68,rgb(58,61,68));drawText(xs[i]+8,50,labels[i],rgb(230,230,230),2);}quad(OX-2,OY-2,OX+W+2,OY+H+2,rgb(225,225,225));glEnable(GL_TEXTURE_2D);glBindTexture(GL_TEXTURE_2D,tex);glColor3f(1,1,1);glBegin(GL_QUADS);glTexCoord2f(0,1);glVertex2f(OX,OY);glTexCoord2f(1,1);glVertex2f(OX+W,OY);glTexCoord2f(1,0);glVertex2f(OX+W,OY+H);glTexCoord2f(0,0);glVertex2f(OX,OY+H);glEnd();glDisable(GL_TEXTURE_2D);quad(0,WH-72,WW,WH,rgb(34,37,43));int x=20;for(auto c:colors){quad(x,WH-57,x+27,WH-30,c);if(c.r==fg.r&&c.g==fg.g&&c.b==fg.b)outline(x-2,WH-59,x+29,WH-28,rgb(255,255,255));x+=32;}drawText(20,WH-22,"1 Pencil  2 Line  3 Rect  4 Ellipse  5 Eraser  6 Text   Ctrl+Z Undo   Ctrl+Y Redo   Ctrl+S Save",rgb(205,205,205),2);if(textMode){quad(OX,OY+H-30,OX+460,OY+H,rgb(248,248,248));drawText(OX+5,OY+H-24,"Text: "+text,rgb(20,20,20),2);}}
static void upload(){glBindTexture(GL_TEXTURE_2D,tex);glTexSubImage2D(GL_TEXTURE_2D,0,0,0,W,H,GL_RGBA,GL_UNSIGNED_BYTE,pix.data());}
static void saveBMP(const char*fn){FILE*f=fopen(fn,"wb");if(!f)return;uint32_t row=((W*3+3)/4)*4,size=row*H+54;unsigned char h[54]={0};h[0]='B';h[1]='M';auto p16=[&](int o,uint16_t v){h[o]=v;h[o+1]=v>>8;};auto p32=[&](int o,uint32_t v){h[o]=v;h[o+1]=v>>8;h[o+2]=v>>16;h[o+3]=v>>24;};p32(2,size);p32(10,54);p32(14,40);p32(18,W);p32(22,H);p16(26,1);p16(28,24);p32(34,row*H);fwrite(h,1,54,f);std::vector<unsigned char>b(row);for(int y=H-1;y>=0;y--){for(int x=0;x<W;x++){size_t i=(y*W+x)*4;b[x*3]=pix[i+2];b[x*3+1]=pix[i+1];b[x*3+2]=pix[i];}fwrite(b.data(),1,row,f);}fclose(f);}
static void commitText(){if(text.empty())return;saveState();drawText(tx-OX,ty-OY,text,fg,3);text.clear();textMode=false;SDL_StopTextInput();}
int main(int argc,char**argv){if(SDL_Init(SDL_INIT_VIDEO)!=0)return 1;SDL_GL_SetAttribute(SDL_GL_DOUBLEBUFFER,1);SDL_Window*w=SDL_CreateWindow("PaintOpenGL - PaintAppX",SDL_WINDOWPOS_CENTERED,SDL_WINDOWPOS_CENTERED,WW,WH,SDL_WINDOW_OPENGL|SDL_WINDOW_RESIZABLE);if(!w)return 1;SDL_GLContext ctx=SDL_GL_CreateContext(w);clearCanvas();glGenTextures(1,&tex);glBindTexture(GL_TEXTURE_2D,tex);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,W,H,0,GL_RGBA,GL_UNSIGNED_BYTE,pix.data());bool run=true;SDL_Event e;while(run){while(SDL_PollEvent(&e)){if(e.type==SDL_QUIT)run=false;else if(e.type==SDL_WINDOWEVENT&&e.window.event==SDL_WINDOWEVENT_SIZE_CHANGED)glViewport(0,0,e.window.data1,e.window.data2);else if(e.type==SDL_TEXTINPUT&&textMode)text+=e.text.text;else if(e.type==SDL_KEYDOWN){int k=e.key.keysym.sym;bool ctrl=(e.key.keysym.mod&KMOD_CTRL);if(textMode){if(k==SDLK_RETURN)commitText();else if(k==SDLK_ESCAPE){text.clear();textMode=false;SDL_StopTextInput();}else if(k==SDLK_BACKSPACE&&!text.empty())text.pop_back();}else if(ctrl&&k==SDLK_z)undo();else if(ctrl&&k==SDLK_y)redo();else if(ctrl&&k==SDLK_s)saveBMP("paint_output.bmp");else if(ctrl&&k==SDLK_n){saveState();clearCanvas();}else if(k==SDLK_1)tool=Tool::Pencil;else if(k==SDLK_2)tool=Tool::Line;else if(k==SDLK_3)tool=Tool::Rect;else if(k==SDLK_4)tool=Tool::Ellipse;else if(k==SDLK_5)tool=Tool::Eraser;else if(k==SDLK_6){tool=Tool::Text;SDL_StartTextInput();}}else if(e.type==SDL_MOUSEMOTION){int mx=e.motion.x,my=e.motion.y;if(drawing&&canvasPoint(mx,my)){int x=mx-OX,y=my-OY;if(tool==Tool::Pencil)line(lx,ly,x,y,fg,3);else if(tool==Tool::Eraser)line(lx,ly,x,y,rgb(255,255,255),20);lx=x;ly=y;}}else if(e.type==SDL_MOUSEBUTTONDOWN&&e.button.button==SDL_BUTTON_LEFT){int mx=e.button.x,my=e.button.y;if(my>=WH-72){int i=(mx-20)/32;if(i>=0&&i<(int)colors.size())fg=colors[i];}else if(my>=46&&my<70){saveState();if(mx>=12&&mx<72)tool=Tool::Pencil;else if(mx>=78&&mx<138)tool=Tool::Eraser;else if(mx>=144&&mx<196)tool=Tool::Line;else if(mx>=202&&mx<274)tool=Tool::Rect;else if(mx>=280&&mx<360)tool=Tool::Ellipse;else if(mx>=366&&mx<430){tool=Tool::Text;SDL_StartTextInput();}else if(mx>=436&&mx<504)fillShape=!fillShape;else if(mx>=510&&mx<576)undo();else if(mx>=582&&mx<648)redo();else if(mx>=654&&mx<720)clearCanvas();else if(mx>=726&&mx<792)saveBMP("paint_output.bmp");}else if(canvasPoint(mx,my)){if(tool==Tool::Text){textMode=true;tx=mx;ty=my;text.clear();SDL_StartTextInput();}else{saveState();drawing=true;sx=lx=mx-OX;sy=ly=my-OY;}}}else if(e.type==SDL_MOUSEBUTTONUP&&e.button.button==SDL_BUTTON_LEFT&&drawing){int x=e.button.x-OX,y=e.button.y-OY;if(tool==Tool::Line)line(sx,sy,x,y,fg,3);else if(tool==Tool::Rect)rectangle(sx,sy,x,y,fg,fillShape);else if(tool==Tool::Ellipse)ellipse(sx,sy,x,y,fg,fillShape);drawing=false;}}upload();render();SDL_GL_SwapWindow(w);SDL_Delay(10);}if(textMode)SDL_StopTextInput();glDeleteTextures(1,&tex);SDL_GL_DeleteContext(ctx);SDL_DestroyWindow(w);SDL_Quit();return 0;}
